def apply_coupon(total, code):
    """Apply coupon `code` to `total`, rounded to cents. Raises ValueError for an unknown code."""
    if code == "SAVE10":
        return round(total * 0.90, 2)
    if code == "FLAT5":
        return round(max(total - 5.00, 0.00), 2)
    raise ValueError(f"unknown coupon code: {code}")

def test_bulk_discount_rate():
    assert bulk_discount(50) == 0.10


def test_apply_coupon_importable():
    assert callable(apply_coupon)
